"use strict";
import { Flex } from "ui/src";
import { Checkbox } from "ui/src/components/checkbox/Checkbox";
import { useIncentivizeContext } from "pages/Incentivize/ContextProvider";
export default function UnderstandCheckbox({ children }) {
  const { termsAccepted, setTermsAccepted } = useIncentivizeContext();
  const checked = termsAccepted;
  return <Flex
    row
    gap={"$gap12"}
    onPress={() => setTermsAccepted(!checked)}
    backgroundColor={checked ? "$surface2" : "$slate"}
    px={"$spacing12"}
    py={"$spacing24"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={checked ? "$surface3" : "$surface2"}
  >
      <Checkbox size={"$icon.16"} checked={checked} />
      {children}
    </Flex>;
}
