"use strict";
import { useAccount } from "hooks/useAccount";
import { useCallback, useEffect, useState } from "react";
import { useTransactionAdder } from "state/transactions/hooks";
import { TransactionType } from "state/transactions/types";
import styled from "styled-components";
import { Flex, SpinningLoader, Text, useSporeColors } from "ui/src";
import { useConnectorClient, useReadContract, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { useIncentivizeContext } from "../ContextProvider";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useEip5792Support } from "uniswap/src/features/transactions/swap/contexts/hooks/useEip5792Support";
import { encodeFunctionData } from "viem";
const ERC20_ABI = [
  {
    inputs: [
      { internalType: "address", name: "spender", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "approve",
    outputs: [{ internalType: "bool", name: "", type: "bool" }],
    stateMutability: "nonpayable",
    type: "function"
  },
  {
    inputs: [
      { internalType: "address", name: "owner", type: "address" },
      { internalType: "address", name: "spender", type: "address" }
    ],
    name: "allowance",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const BRIBE_ABI = [
  {
    inputs: [
      { internalType: "address", name: "token", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "notifyRewardAmount",
    outputs: [],
    stateMutability: "nonpayable",
    type: "function"
  }
];
export default function ChangePoolAndIncentivizeButton() {
  const { setIncentivizeStep, selectedPool, incentiveAmount, incentiveToken, termsAccepted, hasValidBalance } = useIncentivizeContext();
  const colors = useSporeColors();
  const account = useAccount();
  const addTransaction = useTransactionAdder();
  const [flowStep, setFlowStep] = useState(
    "input"
  );
  const [batchId, setBatchId] = useState(null);
  const [isBatched, setIsBatched] = useState(false);
  const bribeAddress = selectedPool?.gauge?.bribeContract;
  const tokenAddress = incentiveToken?.address;
  const supportsEip5792 = useEip5792Support(account.chainId);
  const { data: client } = useConnectorClient();
  const { data: allowance } = useReadContract({
    address: tokenAddress,
    abi: ERC20_ABI,
    functionName: "allowance",
    args: account.address && bribeAddress ? [account.address, bribeAddress] : void 0,
    query: { enabled: !!tokenAddress && !!bribeAddress && !!account.address }
  });
  const needsApproval = useCallback(() => {
    if (!allowance || !incentiveAmount) return true;
    const amountBigInt = BigInt(incentiveAmount.quotient.toString());
    return allowance < amountBigInt;
  }, [allowance, incentiveAmount]);
  const { writeContract, data: writeData, isPending: isWritePending, error: writeError } = useWriteContract();
  const {
    isLoading: isConfirming,
    isSuccess,
    error: receiptError
  } = useWaitForTransactionReceipt({
    hash: writeData
  });
  const executeIncentive = useCallback(async () => {
    if (!account.address || !selectedPool || !incentiveAmount || !incentiveToken || !tokenAddress || !bribeAddress) return;
    try {
      setFlowStep("incentivize");
      const amount = BigInt(incentiveAmount.quotient.toString());
      const approvalNeeded = needsApproval();
      console.log("Submitting incentive:", {
        bribeAddress,
        tokenAddress,
        amount: amount.toString(),
        supportsEip5792,
        approvalNeeded
      });
      if (supportsEip5792 && approvalNeeded && client) {
        console.log("\u{1F504} Using EIP-5792 batched transactions");
        const approveData = encodeFunctionData({
          abi: ERC20_ABI,
          functionName: "approve",
          args: [bribeAddress, BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff")]
        });
        const incentiveData = encodeFunctionData({
          abi: BRIBE_ABI,
          functionName: "notifyRewardAmount",
          args: [tokenAddress, amount]
        });
        console.log("Batch call data:", {
          approveData,
          incentiveData,
          tokenAddress,
          bribeAddress,
          amount: amount.toString()
        });
        const result = await client.request({
          method: "wallet_sendCalls",
          params: [{
            version: "2.0.0",
            chainId: `0x${account.chainId?.toString(16)}`,
            from: account.address,
            calls: [
              {
                to: tokenAddress,
                data: approveData,
                value: "0x0"
              },
              {
                to: bribeAddress,
                data: incentiveData,
                value: "0x0"
              }
            ],
            atomicRequired: true
          }]
        });
        if (result?.id) {
          setBatchId(result.id);
          setIsBatched(true);
          setFlowStep("confirming");
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: result.id }, result.id);
          setTimeout(() => {
            setFlowStep("success");
            const poolName = selectedPool?.symbol || "pool";
            const amountStr = incentiveAmount?.toSignificant(6) || "0";
            const token = incentiveToken?.symbol || "tokens";
            popupRegistry.addPopup({
              type: PopupType.IncentiveSuccess,
              content: {
                type: "success",
                title: "Incentive Deposited",
                description: `Successfully deposited ${amountStr} ${token} as incentive for ${poolName}`,
                hash: result.id,
                action: "deposit"
              }
            }, `incentive-deposit-success-${result.id}`);
            setTimeout(() => {
              setIncentivizeStep("step-1");
              setFlowStep("input");
              setBatchId(null);
              setIsBatched(false);
            }, 2e3);
          }, 3e3);
        }
      } else {
        console.log("\u{1F4DD} Using separate transactions (no batching support)");
        if (approvalNeeded) {
          const maxAmount = BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
          const approvalResult = await writeContract({
            address: tokenAddress,
            abi: ERC20_ABI,
            functionName: "approve",
            args: [bribeAddress, maxAmount]
          });
          await new Promise((resolve) => setTimeout(resolve, 1e3));
        }
        const result = await writeContract({
          address: bribeAddress,
          abi: BRIBE_ABI,
          functionName: "notifyRewardAmount",
          args: [tokenAddress, amount]
        });
        if (result) {
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: result }, result);
        }
      }
    } catch (error) {
      console.error("Incentivization failed:", error);
      setFlowStep("error");
      popupRegistry.addPopup({
        type: PopupType.IncentiveError,
        content: {
          type: "error",
          title: "Incentive Deposit Failed",
          description: `Failed to deposit incentive: ${error.message}`,
          action: "deposit"
        }
      }, `incentive-deposit-error-${Date.now()}`);
    }
  }, [writeContract, account.address, selectedPool, incentiveAmount, incentiveToken, tokenAddress, bribeAddress, supportsEip5792, client, needsApproval]);
  useEffect(() => {
    if (isBatched) return;
    if (isConfirming) {
      setFlowStep("confirming");
    } else if (isSuccess && (flowStep === "incentivize" || flowStep === "confirming")) {
      setFlowStep("success");
      const poolName = selectedPool?.symbol || "pool";
      const amount = incentiveAmount?.toSignificant(6) || "0";
      const token = incentiveToken?.symbol || "tokens";
      popupRegistry.addPopup({
        type: PopupType.IncentiveSuccess,
        content: {
          type: "success",
          title: "Incentive Deposited",
          description: `Successfully deposited ${amount} ${token} as incentive for ${poolName}`,
          hash: writeData,
          action: "deposit"
        }
      }, `incentive-deposit-success-${writeData}`);
      if (writeData && tokenAddress && bribeAddress && incentiveAmount) {
        addTransaction(
          { hash: writeData },
          {
            type: TransactionType.APPROVAL,
            // TODO: Add INCENTIVE type if needed
            tokenAddress,
            spender: bribeAddress,
            amount: incentiveAmount.quotient.toString()
          }
        );
      }
      setTimeout(() => {
        setIncentivizeStep("step-1");
        setFlowStep("input");
      }, 2e3);
    } else if (writeError || receiptError) {
      const error = writeError || receiptError;
      const errorMessage = error?.message || "Transaction failed";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied");
      if (isUserRejection) {
        setFlowStep("input");
      } else {
        setFlowStep("error");
      }
    }
  }, [
    isConfirming,
    isSuccess,
    writeError,
    receiptError,
    flowStep,
    writeData,
    tokenAddress,
    bribeAddress,
    incentiveAmount,
    addTransaction,
    setIncentivizeStep,
    selectedPool,
    incentiveToken,
    isBatched
  ]);
  const Button = styled.button`
    all: unset;
    padding: 16px 10px;
    background-color: ${(props) => props.$disabled ? colors.surface2.val : props.$lock ? colors.surface2Hovered.val : colors.accent1.val};
    color: ${(props) => props.$disabled ? colors.neutral3.val : props.$lock ? colors.neutral1.val : colors.surface1.val};
    border-radius: 12px;
    border: 1px solid ${colors.surface3.val};
    cursor: ${(props) => props.$disabled ? "not-allowed" : "pointer"};
    display: flex;
    justify-content: center;
    align-items: center;
    flex-grow: 1;
    transition: all 0.2s ease;
    &:hover {
      opacity: ${(props) => props.$disabled ? 1 : 0.7};
    }
  `;
  const isProcessing = isWritePending || isConfirming;
  const isDisabled = isProcessing || !account.address || !selectedPool || !incentiveAmount || !incentiveToken || !termsAccepted || !hasValidBalance;
  const getButtonText = () => {
    if (!hasValidBalance && incentiveAmount) return "Insufficient Balance";
    if (!termsAccepted) return "Accept terms tirst";
    if (flowStep === "incentivize") return "Submitting...";
    if (flowStep === "confirming") return "Confirming...";
    if (flowStep === "success") return "Success!";
    if (flowStep === "error") return "Try Again";
    return "Incentivize";
  };
  return <Flex mt={"$spacing24"} row gap={"$gap12"} alignItems="center">
      {
    /* <Button role="button" $lock onClick={() => setIncentivizeStep('step-1')}>
      <Text variant="buttonLabel3" color={'inherit'}>
        Change Pool
      </Text>
    </Button> */
  }
      <Button role="button" onClick={executeIncentive} $disabled={isDisabled}>
        <Flex row gap={"$gap8"} alignItems="center">
          {(flowStep === "incentivize" || flowStep === "confirming") && <SpinningLoader size={20} />}
          <Text variant="buttonLabel3" color={"inherit"}>
            {getButtonText()}
          </Text>
        </Flex>
      </Button>
    </Flex>;
}
